const trainingCapstoneFiles={"train_ddp.py": "\"\"\"Small, reproducible DDP lab. Run with torchrun; see README.md.\n\nEpoch-boundary recovery only, with a fixed world size and fixed batch settings.\nSynthetic classification data exercises the training plumbing, not LLM performance.\n\"\"\"\nimport argparse\nfrom contextlib import nullcontext\nfrom datetime import timedelta\nimport json\nimport os\nfrom pathlib import Path\nimport time\n\nimport torch\nfrom torch import nn\nimport torch.distributed as dist\nfrom torch.nn.parallel import DistributedDataParallel as DDP\nfrom torch.utils.data import DataLoader, TensorDataset, DistributedSampler\n\n\ndef arguments():\n    p = argparse.ArgumentParser(description=__doc__)\n    p.add_argument('--device', choices=['cpu', 'cuda'], default='cuda')\n    p.add_argument('--epochs', type=int, default=4, help='Total target epochs, including resumed epochs')\n    p.add_argument('--batch-size', type=int, default=64, help='Per-rank microbatch')\n    p.add_argument('--accum', type=int, default=2)\n    p.add_argument('--samples', type=int, default=8192)\n    p.add_argument('--hidden', type=int, default=256)\n    p.add_argument('--seed', type=int, default=23)\n    p.add_argument('--precision', choices=['fp32', 'bf16', 'fp16'], default='fp32')\n    p.add_argument('--save-dir', default='runs/demo')\n    p.add_argument('--resume', default='')\n    a = p.parse_args()\n    if min(a.epochs, a.batch_size, a.accum, a.samples, a.hidden) < 1:\n        p.error('epochs, batch-size, accum, samples and hidden must be positive')\n    if a.device == 'cpu' and a.precision != 'fp32':\n        p.error('This CPU verification path supports fp32 only')\n    if not all(k in os.environ for k in ('RANK', 'LOCAL_RANK', 'WORLD_SIZE')):\n        p.error('Use torchrun, even for a single process; see README.md')\n    return a\n\n\ndef report(rank, **record):\n    if rank == 0:\n        print(json.dumps(record, ensure_ascii=False), flush=True)\n\n\ndef save_checkpoint(path, model, optimizer, scaler, loader_rng, epoch, signature, device, rank, world):\n    save_began = time.perf_counter()\n    # Small teaching example: gather RNG state, not model tensors, to rank 0.\n    rng = {'cpu': torch.get_rng_state(), 'loader': loader_rng.get_state()}\n    if device.type == 'cuda':\n        rng['cuda'] = torch.cuda.get_rng_state(device)\n    all_rng = [None] * world if rank == 0 else None\n    dist.gather_object(rng, all_rng, dst=0)\n    if rank == 0:\n        path.parent.mkdir(parents=True, exist_ok=True)\n        temporary = path.with_name(path.name + '.tmp')\n        payload = {'model': model.module.state_dict(), 'optimizer': optimizer.state_dict(),\n                   'scaler': scaler.state_dict(), 'next_epoch': epoch + 1,\n                   'signature': signature, 'rng_by_rank': all_rng}\n        # Same-directory replace is atomic on a suitable POSIX filesystem.\n        # Not an object-storage commit protocol and not a power-loss guarantee.\n        with temporary.open('wb') as f:\n            torch.save(payload, f)\n            f.flush()\n            os.fsync(f.fileno())\n        os.replace(temporary, path)\n    dist.barrier()\n    report(rank, event='checkpoint', path=str(path), next_epoch=epoch + 1,\n           seconds=time.perf_counter() - save_began)\n\n\ndef train(a):\n    rank, local_rank, world = (int(os.environ[k]) for k in ('RANK', 'LOCAL_RANK', 'WORLD_SIZE'))\n    torch.set_num_threads(1)\n    if a.device == 'cuda':\n        if not torch.cuda.is_available() or local_rank >= torch.cuda.device_count():\n            raise RuntimeError('Each local process needs a distinct visible CUDA GPU')\n        torch.cuda.set_device(local_rank)\n        device = torch.device('cuda', local_rank)\n        if a.precision == 'bf16' and not torch.cuda.is_bf16_supported():\n            raise RuntimeError('BF16 is not supported by this device/runtime; use fp32 or fp16')\n    else:\n        device = torch.device('cpu')\n    dist.init_process_group('nccl' if a.device == 'cuda' else 'gloo', timeout=timedelta(seconds=120))\n    try:\n        # Identical fixed dataset across ranks. No external dataset download required.\n        data_rng = torch.Generator().manual_seed(a.seed)\n        x = torch.randn(a.samples, 128, generator=data_rng)\n        teacher = torch.randn(128, 10, generator=data_rng)\n        y = (x @ teacher).argmax(dim=1)\n        dataset = TensorDataset(x, y)\n        sampler = DistributedSampler(dataset, num_replicas=world, rank=rank,\n                                     shuffle=True, seed=a.seed, drop_last=True)\n        loader_rng = torch.Generator().manual_seed(a.seed + 1000 + rank)\n        loader = DataLoader(dataset, batch_size=a.batch_size, sampler=sampler,\n                            drop_last=True, num_workers=0, pin_memory=a.device == 'cuda',\n                            generator=loader_rng)\n        if len(loader) == 0 or len(loader) % a.accum:\n            raise ValueError('Per-rank batch count must be positive and divisible by --accum; '\n                             'adjust --samples/--batch-size/--accum')\n        torch.manual_seed(a.seed)\n        raw_model = nn.Sequential(nn.Linear(128, a.hidden), nn.ReLU(), nn.Dropout(0.1),\n                                  nn.Linear(a.hidden, 10)).to(device)\n        model = DDP(raw_model, device_ids=[local_rank] if a.device == 'cuda' else None,\n                    broadcast_buffers=False)\n        # Fix the non-fused path: its post hook observes a completed step call.\n        optimizer = torch.optim.AdamW(model.parameters(), lr=1e-3, fused=False)\n        applied_calls = 0\n\n        def count_step(_optimizer, _args, _kwargs):\n            nonlocal applied_calls\n            applied_calls += 1\n\n        optimizer.register_step_post_hook(count_step)\n        scaler = torch.amp.GradScaler('cuda', enabled=a.precision == 'fp16')\n        torch.manual_seed(a.seed + rank)  # Independent dropout streams, restored on resume.\n        signature = {k: getattr(a, k) for k in ('device', 'precision', 'batch_size', 'accum',\n                                                'samples', 'hidden', 'seed')}\n        signature['world_size'] = world\n        start = 0\n        if a.resume:\n            # Only load a trusted checkpoint from this lab. Every rank must read the same file.\n            state = torch.load(a.resume, map_location='cpu', weights_only=True)\n            if state['signature'] != signature:\n                raise ValueError('Resume requires the same world size, device, precision and training settings')\n            model.module.load_state_dict(state['model'])\n            optimizer.load_state_dict(state['optimizer'])\n            # Older lab checkpoints may store fused=None in the parameter groups.\n            for group in optimizer.param_groups:\n                group['fused'] = False\n            scaler.load_state_dict(state['scaler'])\n            start = state['next_epoch']\n            torch.set_rng_state(state['rng_by_rank'][rank]['cpu'])\n            loader_rng.set_state(state['rng_by_rank'][rank]['loader'])\n            if a.device == 'cuda':\n                torch.cuda.set_rng_state(state['rng_by_rank'][rank]['cuda'], device)\n        if start >= a.epochs:\n            raise ValueError('--epochs is the total target and must be greater than checkpoint next_epoch')\n        effective_batch = a.batch_size * a.accum * world\n        report(rank, event='start', world_size=world, backend=dist.get_backend(),\n               effective_batch=effective_batch, start_epoch=start, precision=a.precision,\n               torch_version=str(torch.__version__))\n        for epoch in range(start, a.epochs):\n            sampler.set_epoch(epoch)\n            model.train()\n            optimizer.zero_grad(set_to_none=True)\n            loss_sum = torch.zeros((), device=device)\n            seen = 0\n            attempted_windows = 0\n            applied_at_start = applied_calls\n            dist.barrier()\n            if a.device == 'cuda':\n                torch.cuda.synchronize(device)\n            began = time.perf_counter()\n            for step, (features, labels) in enumerate(loader):\n                features = features.to(device, non_blocking=True)\n                labels = labels.to(device, non_blocking=True)\n                update = (step + 1) % a.accum == 0\n                # no_sync must cover BOTH forward and backward.\n                with nullcontext() if update else model.no_sync():\n                    with torch.autocast(device_type=a.device,\n                                        dtype=torch.bfloat16 if a.precision == 'bf16' else torch.float16,\n                                        enabled=a.precision != 'fp32'):\n                        loss = nn.functional.cross_entropy(model(features), labels)\n                    scaler.scale(loss / a.accum).backward()\n                loss_sum += loss.detach() * labels.numel()\n                seen += labels.numel()\n                if update:\n                    attempted_windows += 1\n                    scaler.step(optimizer)\n                    scaler.update()\n                    optimizer.zero_grad(set_to_none=True)\n            if a.device == 'cuda':\n                torch.cuda.synchronize(device)\n            duration = torch.tensor(time.perf_counter() - began, device=device, dtype=torch.float64)\n            totals = torch.stack((loss_sum.double(), torch.tensor(float(seen), device=device, dtype=torch.float64)))\n            dist.all_reduce(duration, op=dist.ReduceOp.MAX)\n            dist.all_reduce(totals, op=dist.ReduceOp.SUM)\n            applied_this_epoch = applied_calls - applied_at_start\n            counts = torch.tensor([attempted_windows, applied_this_epoch], device=device)\n            minimum, maximum = counts.clone(), counts.clone()\n            dist.all_reduce(minimum, op=dist.ReduceOp.MIN)\n            dist.all_reduce(maximum, op=dist.ReduceOp.MAX)\n            if not torch.equal(minimum, maximum):\n                raise RuntimeError('Ranks disagree on attempted windows or applied optimizer calls')\n            report(rank, event='epoch', epoch=epoch + 1, loss=(totals[0] / totals[1]).item(),\n                   samples=int(totals[1].item()), seconds=duration.item(),\n                   samples_per_second=(totals[1] / duration).item(),\n                   attempted_update_windows=attempted_windows,\n                   applied_optimizer_steps=applied_this_epoch,\n                   optimizer_steps=applied_this_epoch)\n            save_checkpoint(Path(a.save_dir) / 'checkpoint.pt', model, optimizer, scaler,\n                            loader_rng, epoch, signature, device, rank, world)\n    finally:\n        dist.destroy_process_group()\n\n\nif __name__ == '__main__':\n    train(arguments())\n", "compare_checkpoints.py": "\"\"\"Compare model, optimizer, scaler and RNG state after uninterrupted/resumed CPU runs.\"\"\"\nimport argparse\nimport torch\n\n\ndef compare(a, b, path='state'):\n    if isinstance(a, torch.Tensor):\n        if not isinstance(b, torch.Tensor) or a.dtype != b.dtype or a.shape != b.shape:\n            raise AssertionError(f'{path}: tensor metadata differs')\n        if not torch.equal(a, b):\n            raise AssertionError(f'{path}: tensor values differ')\n    elif isinstance(a, dict):\n        if a.keys() != b.keys():\n            raise AssertionError(f'{path}: keys differ')\n        for k in a:\n            compare(a[k], b[k], f'{path}.{k}')\n    elif isinstance(a, (tuple, list)):\n        if len(a) != len(b):\n            raise AssertionError(f'{path}: lengths differ')\n        for i, (x, y) in enumerate(zip(a, b)):\n            compare(x, y, f'{path}[{i}]')\n    elif a != b:\n        raise AssertionError(f'{path}: {a!r} != {b!r}')\n\n\nif __name__ == '__main__':\n    p = argparse.ArgumentParser(description=__doc__)\n    p.add_argument('uninterrupted')\n    p.add_argument('resumed')\n    args = p.parse_args()\n    a = torch.load(args.uninterrupted, map_location='cpu', weights_only=True)\n    b = torch.load(args.resumed, map_location='cpu', weights_only=True)\n    compare(a, b)\n    print('PASS: model, optimizer, scaler, RNG, epoch and configuration are exactly equal.')\n", "verify_run.py": "\"\"\"Bounded CPU/Gloo recovery capstone; run with Python 3.10-3.12 and PyTorch 2.5.1.\n\nUses only this directory's trusted training scripts and temporary checkpoints.\nThe two-epoch run exits normally; this does not simulate a mid-step crash.\n\"\"\"\nimport argparse\nfrom datetime import datetime, timezone\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport platform\nimport signal\nimport subprocess\nimport sys\nimport tempfile\n\nimport torch\n\n\nLAB = Path(__file__).resolve().parent\n\n\ndef digest(path):\n    return hashlib.sha256(path.read_bytes()).hexdigest()\n\n\ndef run(argv, directory, expected_error=None):\n    env = dict(os.environ, OMP_NUM_THREADS=\"1\")\n    process = subprocess.Popen(argv, cwd=directory, env=env, text=True,\n                               stdout=subprocess.PIPE, stderr=subprocess.PIPE, start_new_session=True)\n    try:\n        stdout, stderr = process.communicate(timeout=60)\n    except subprocess.TimeoutExpired:\n        # Only supervise our own trusted launcher/worker process group.\n        try:\n            os.killpg(process.pid, signal.SIGTERM)\n        except ProcessLookupError:\n            pass\n        try:\n            process.communicate(timeout=5)\n        except subprocess.TimeoutExpired:\n            try:\n                os.killpg(process.pid, signal.SIGKILL)\n            except ProcessLookupError:\n                pass\n            process.communicate()\n        raise RuntimeError(\"training command exceeded 60s; its process group was stopped\")\n    result = subprocess.CompletedProcess(argv, process.returncode, stdout, stderr)\n    if expected_error is not None:\n        if result.returncode == 0 or expected_error not in result.stderr:\n            raise AssertionError(\"expected rejection: \" + expected_error + \"\\n\" + result.stderr[-4000:])\n        return {\"exit_code\": result.returncode, \"matched_error\": expected_error}\n    if result.returncode:\n        raise AssertionError(\"command failed\\n\" + result.stderr[-4000:])\n    records = []\n    for line in result.stdout.splitlines():\n        if line.startswith(\"{\"):\n            record = json.loads(line)\n            if \"path\" in record:\n                record[\"path\"] = str(Path(record[\"path\"]).relative_to(directory))\n            records.append(record)\n    return {\"exit_code\": 0, \"records\": records, \"message\": result.stdout.strip() if not records else \"\"}\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\"--report\", default=\"run-report.json\")\n    args = parser.parse_args()\n    if os.name != \"posix\":\n        parser.error(\"this supervisor uses POSIX process groups; use Linux/macOS\")\n    if any(name in os.environ for name in (\"RANK\", \"LOCAL_RANK\", \"WORLD_SIZE\")):\n        parser.error(\"run verify_run.py directly, outside torchrun\")\n    report = {\"verified_at_utc\": datetime.now(timezone.utc).isoformat(),\n              \"environment\": {\"python\": platform.python_version(), \"torch\": str(torch.__version__),\n                              \"platform\": platform.platform(), \"device\": \"cpu\", \"backend\": \"gloo\"},\n              \"source_sha256\": {name: digest(LAB/name) for name in\n                                (\"train_ddp.py\", \"compare_checkpoints.py\", \"verify_run.py\")},\n              \"configuration\": {\"world_size\": 2, \"samples\": 1024, \"hidden\": 32,\n                                \"batch_size_per_rank\": 32, \"accum\": 2, \"seed\": 23,\n                                \"precision\": \"fp32\", \"target_epochs\": 4},\n              \"runs\": {}, \"negative_probes\": {}}\n    with tempfile.TemporaryDirectory(prefix=\"infra-training-capstone-\") as temporary:\n        directory = Path(temporary)\n\n        def train(label, epochs, resume=None, changed=None, expected_error=None):\n            output = directory/label\n            config = {\"device\": \"cpu\", \"samples\": 1024, \"hidden\": 32, \"batch-size\": 32, \"accum\": 2}\n            config.update(changed or {})\n            argv = [sys.executable, \"-m\", \"torch.distributed.run\", \"--standalone\", \"--nproc-per-node=2\",\n                    str(LAB/\"train_ddp.py\"), \"--epochs=\"+str(epochs), \"--save-dir=\"+str(output)]\n            argv += [\"--\"+name+\"=\"+str(value) for name, value in config.items()]\n            if resume is not None:\n                argv.append(\"--resume=\"+str(resume))\n            result = run(argv, directory, expected_error)\n            if expected_error is not None:\n                result[\"checkpoint_created\"] = (output/\"checkpoint.pt\").exists()\n                assert not result[\"checkpoint_created\"]\n                return result\n            start = next(row for row in result[\"records\"] if row[\"event\"] == \"start\")\n            epochs_seen = [row for row in result[\"records\"] if row[\"event\"] == \"epoch\"]\n            first = 2 if resume is not None else 0\n            assert start[\"world_size\"] == 2 and start[\"effective_batch\"] == 128\n            assert start[\"start_epoch\"] == first\n            assert [row[\"epoch\"] for row in epochs_seen] == list(range(first+1, epochs+1))\n            for row in epochs_seen:\n                assert row[\"samples\"] == 1024\n                assert row[\"attempted_update_windows\"] == row[\"applied_optimizer_steps\"] == 8\n            result[\"applied_calls_this_run\"] = sum(row[\"applied_optimizer_steps\"] for row in epochs_seen)\n            report[\"runs\"][label] = result\n            return output/\"checkpoint.pt\"\n\n        full = train(\"full\", 4)\n        split = train(\"split\", 2)\n        resumed = train(\"resumed\", 4, resume=split)\n        compare_command = [sys.executable, str(LAB/\"compare_checkpoints.py\")]\n        report[\"full_state_comparison\"] = run(compare_command+[str(full), str(resumed)], directory)\n        final = torch.load(resumed, map_location=\"cpu\", weights_only=True)\n        assert final[\"next_epoch\"] == 4 and len(final[\"rng_by_rank\"]) == 2\n        report[\"final_state\"] = {\"next_epoch\": final[\"next_epoch\"],\n                                 \"rng_rank_count\": len(final[\"rng_by_rank\"]),\n                                 \"compared_fields\": sorted(final.keys())}\n\n        report[\"negative_probes\"][\"nondivisible_window\"] = train(\n            \"bad-accum\", 4, changed={\"accum\": 3},\n            expected_error=\"Per-rank batch count must be positive and divisible by --accum\")\n        report[\"negative_probes\"][\"changed_configuration\"] = train(\n            \"bad-signature\", 4, resume=split, changed={\"hidden\": 16},\n            expected_error=\"Resume requires the same world size, device, precision and training settings\")\n\n        # Preserve model weights, change only one Adam moment: a weights-only oracle must miss this.\n        damaged = torch.load(resumed, map_location=\"cpu\", weights_only=True)\n        moment = next(state[\"exp_avg\"] for state in damaged[\"optimizer\"][\"state\"].values())\n        moment.view(-1)[0] += 0.25\n        assert all(torch.equal(value, damaged[\"model\"][key]) for key, value in final[\"model\"].items())\n        bad_path = directory/\"changed-adam.pt\"\n        torch.save(damaged, bad_path)\n        probe = run(compare_command+[str(full), str(bad_path)], directory,\n                    expected_error=\"state.optimizer.state\")\n        probe[\"model_weights_unchanged\"] = True\n        probe[\"changed_field\"] = \"first exp_avg element + 0.25\"\n        report[\"negative_probes\"][\"changed_optimizer_state\"] = probe\n\n    report[\"status\"] = \"passed\"\n    target = Path(args.report)\n    target.parent.mkdir(parents=True, exist_ok=True)\n    target.write_text(json.dumps(report, ensure_ascii=False, indent=2)+\"\\n\")\n    print(json.dumps(report, ensure_ascii=False))\n\n\nif __name__ == \"__main__\":\n    main()\n"};
